package dev.kpaths.codegen.model

/** Prefix reserved for implementation declarations generated by KPaths. */
public const val KPATHS_INTERNAL_PREFIX: String = "__kpaths_"

/** Whether a source identifier conflicts with the reserved implementation prefix. */
public fun isKPathsReservedName(name: String): Boolean = name.startsWith(KPATHS_INTERNAL_PREFIX)

/** Reasons an explicitly configured generated name cannot be used. */
public enum class KPathsConfiguredNameError { EMPTY, RESERVED, INVALID }

/** Validate a configured Kotlin identifier without rejecting escapable Kotlin keywords. */
public fun validateKPathsConfiguredName(name: String): KPathsConfiguredNameError? = when {
  name.isEmpty() -> KPathsConfiguredNameError.EMPTY
  isKPathsReservedName(name) -> KPathsConfiguredNameError.RESERVED
  !(name.first().isLetter() || name.first() == '_') ||
    name.drop(1).any { !it.isLetterOrDigit() && it != '_' } -> KPathsConfiguredNameError.INVALID
  else -> null
}

/** Render the shared diagnostic for an invalid annotation name. */
public fun kPathsConfiguredNameDiagnostic(annotation: String, name: String, error: KPathsConfiguredNameError): String = when (error) {
  KPathsConfiguredNameError.EMPTY -> "$annotation requires a non-empty Kotlin identifier."
  KPathsConfiguredNameError.RESERVED -> "$annotation value '$name' uses the reserved '$KPATHS_INTERNAL_PREFIX' prefix for KPaths-generated implementation details."
  KPathsConfiguredNameError.INVALID -> "$annotation value '$name' must be a single Kotlin identifier, without a package or dot."
}

/** A member a frontend intends to generate in one namespace. */
public data class KPathsGeneratedMember(public val name: String, public val description: String)

/** Members which would occupy the same generated name. */
public data class KPathsGeneratedMemberCollision(
  public val name: String,
  public val members: List<KPathsGeneratedMember>,
)

/** Finds conflicts within one generated namespace, preserving declaration order. */
public fun findKPathsGeneratedMemberCollisions(
  members: List<KPathsGeneratedMember>,
): List<KPathsGeneratedMemberCollision> = members.groupBy(KPathsGeneratedMember::name)
  .filterValues { it.size > 1 }
  .map { (name, collisions) -> KPathsGeneratedMemberCollision(name, collisions) }
